test('1 de 3 pontos done -> 33% via Math.round (valor-limite: arredondamento de fração)', () => {
  // Verifica o arredondamento: 1/3 = 33.33% deve virar 33 (Math.round arredonda pra baixo aqui). (valor-limite)
