  // Arrange
  const stories = [
    { status: 'done', story_points: 1 },
    { status: 'to_do', story_points: 2 },
  ];
  // Act
  const r = calcularMetricasSprint(stories);
  // Assert
  expect(r.percentDone).toBe(33); // round(1/3*100) = round(33.33) = 33
});

